// SPDX-License-Identifier: ISC
//! Replay of frozen go-flags front-end vectors generated by a
//! package-main dump test at release-v2.1.5: 52 scenarios drive
//! dcrd's real loadConfig with syntax-heavy command lines (short
//! options in separate, concatenated, and `=` forms, double dashes,
//! quoted values, base-zero integers, conversion failures with
//! go-flags' exact marshal error texts), the INI grammar (quoted
//! values, bool forms, field/short-name matching, sections, and the
//! per-line error texts), and the environment variable defaults —
//! compared field for field through the raw-argv entry point.

// Index arithmetic over pinned vector rows.
#![allow(clippy::arithmetic_side_effects)]

use std::collections::BTreeMap;
use std::fs;

use dcroxide_node::config::ConfigEnv;
use dcroxide_node::load_config_from_argv;

mod common;
use common::emit_cfg;

const VECTORS: &str = include_str!("data/flags_vectors.txt");

/// One scenario's parsed input rows.
#[derive(Default)]
struct Scenario {
    name: String,
    args: Vec<String>,
    conf: Vec<String>,
    env: Vec<(String, String)>,
    expect_ok: Option<String>,
    expect_err: Option<String>,
}

#[test]
fn flags_front_end_matches_dcrd() {
    let mut scenarios: BTreeMap<usize, Scenario> = BTreeMap::new();

    for line in VECTORS.lines() {
        let fields: Vec<&str> = line.splitn(4, '|').collect();
        let n: usize = fields[1].parse().unwrap();
        let sc = scenarios.entry(n).or_default();
        match fields[0] {
            "cscen" => sc.name = fields[2].to_string(),
            "carg" => sc
                .args
                .push(line.splitn(3, '|').nth(2).unwrap().to_string()),
            "cfile" => sc
                .conf
                .push(line.splitn(3, '|').nth(2).unwrap().to_string()),
            "cenv" => sc.env.push((fields[2].to_string(), fields[3].to_string())),
            "cok" => sc.expect_ok = Some(line.splitn(3, '|').nth(2).unwrap().to_string()),
            "cerr" => sc.expect_err = Some(line.splitn(3, '|').nth(2).unwrap().to_string()),
            other => panic!("unknown row tag {other}"),
        }
    }
    assert_eq!(scenarios.len(), 52, "unexpected scenario count");

    for (n, sc) in &scenarios {
        // dcrd registers the service options group only on Windows,
        // so this posix-truth rejection scenario does not apply there.
        if cfg!(windows) && sc.name == "service flag not on posix" {
            continue;
        }
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path().to_string_lossy().into_owned();

        fs::write(home_dir.path().join("dcroxide.conf"), sc.conf.join("\n")).unwrap();

        let args: Vec<String> = sc.args.iter().map(|a| a.replace("@HOME@", &home)).collect();
        let env_vars: BTreeMap<String, String> = sc
            .env
            .iter()
            .map(|(k, v)| (k.clone(), v.replace("@HOME@", &home)))
            .collect();

        let getenv = move |name: &str| env_vars.get(name).cloned();
        let env = ConfigEnv {
            default_home_dir: "/dcroxide-nonexistent-default".to_string(),
            lookup_localhost: Box::new(|| Ok(vec!["::1".to_string(), "127.0.0.1".to_string()])),
            interface_by_name: Box::new(|_| None),
            getenv: Box::new(getenv.clone()),
            user_home: Box::new(|_| None),
            rand_bytes: Box::new(|b: &mut [u8]| b.fill(0x42)),
        };

        match load_config_from_argv(&args, &env) {
            Ok((cfg, remaining)) => {
                let expected = sc
                    .expect_ok
                    .as_ref()
                    .unwrap_or_else(|| panic!("scenario {n} {}: expected error", sc.name));
                // A relocated home creates a default config with
                // generated credentials, tokenized like the dump.
                let norm_creds = sc.name == "short appdata";
                let got = emit_cfg(&cfg, &remaining, &home, norm_creds);
                assert_eq!(&got, expected, "scenario {n}: {}", sc.name);
            }
            Err(err) => {
                let expected = sc
                    .expect_err
                    .as_ref()
                    .unwrap_or_else(|| panic!("scenario {n} {}: unexpected error {err}", sc.name));
                let got = common::as_dcrd_names(&err.replace(&home, "@HOME@"));
                assert_eq!(&got, expected, "scenario {n}: {}", sc.name);
            }
        }
    }
}

/// The `-s/--service` option parses in both forms on Windows, where
/// dcrd registers the service options group (the posix rejection is
/// pinned by the vector scenarios), and the load hands the command back
/// for the caller to run straight after the version check, as dcrd's
/// `loadConfig` runs `runServiceCommand` and exits.
#[cfg(windows)]
#[test]
fn the_service_command_option_parses() {
    for args in [
        vec!["-s".to_string(), "install".to_string()],
        vec!["--service=stop".to_string()],
    ] {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path().to_string_lossy().into_owned();
        let mut full_args = vec![format!("--appdata={home}")];
        full_args.extend(args.clone());
        let env = ConfigEnv {
            default_home_dir: "/dcroxide-nonexistent-default".to_string(),
            lookup_localhost: Box::new(|| Ok(vec!["::1".to_string(), "127.0.0.1".to_string()])),
            interface_by_name: Box::new(|_| None),
            getenv: Box::new(|_| None),
            user_home: Box::new(|_| None),
            rand_bytes: Box::new(|b: &mut [u8]| b.fill(0x42)),
        };
        let err = match load_config_from_argv(&full_args, &env) {
            Ok(_) => panic!("args {args:?}: the service command must end the load"),
            Err(err) => err,
        };
        let expected = if args[0] == "-s" { "install" } else { "stop" };
        assert_eq!(
            err,
            format!(
                "{}{expected}",
                dcroxide_node::config::ERR_SERVICE_COMMAND_PREFIX
            ),
            "args {args:?}"
        );
    }
}

/// The application data directory `tools/helpgen` fills dcrd's
/// defaults in over (its `helpHome`), standing in for the machine's own:
/// the help shows the defaults, so the vector depends on it.
const HELP_VECTOR_HOME: &str = "/home/user/.dcroxide";

/// The help rendered with dcrd's environment-variable names, because
/// that is what the vectors are dumps of.  The port reads
/// `DCROXIDE_APPDATA` and `DCROXIDE_ALT_DNSNAMES` instead (see
/// `ENV_DEFAULTS`), and those are four characters longer, which changes
/// where go-flags wraps the `[$VAR]` annotation.  Feeding the vectors'
/// own names keeps the parity tests measuring what they exist to
/// measure — the column layout, the wrapping, the option ordering —
/// instead of failing over an input the port deliberately changed.  The
/// production rendering is pinned by
/// `the_env_annotations_name_the_variables_actually_read`.
fn render_as_dcrd(terminal_columns: usize) -> String {
    let as_dcrd: Vec<(&str, &str, Option<&str>)> = dcroxide_node::flags::HELP_DESCRIPTIONS
        .iter()
        .map(|&(long, desc, env)| {
            let env = match env {
                Some("DCROXIDE_APPDATA") => Some("DCRD_APPDATA"),
                Some("DCROXIDE_ALT_DNSNAMES") => Some("DCRD_ALT_DNSNAMES"),
                other => other,
            };
            (long, desc, env)
        })
        .collect();
    let rendered = dcroxide_node::flags::render_help_with(
        "dcroxide",
        &as_dcrd,
        HELP_VECTOR_HOME,
        terminal_columns,
    );
    String::from_utf8(rendered).expect("the vector home renders as UTF-8")
}

/// The rendered help matches go-flags' output for dcrd's option
/// registry byte for byte (`tools/helpgen` regenerates the vector with
/// no terminal on stdin, where go-flags wraps at eighty columns), with
/// the `(default: X)` note go-flags adds for every option dcrd's
/// defaulted config gives a non-zero value.  A terminal reporting zero
/// columns wraps at eighty too (`getAlignmentInfo`).
#[test]
fn help_text_matches_the_go_flags_vector() {
    let expected = include_str!("data/help_vector.txt");
    assert_eq!(
        render_as_dcrd(80),
        expected,
        "help text must match go-flags"
    );
    assert_eq!(
        render_as_dcrd(0),
        expected,
        "a zero-column terminal wraps at eighty"
    );
}

/// go-flags wraps the help to the width of the terminal on stdin, not
/// a fixed eighty columns: `help_vector_140.txt` is `tools/helpgen` run
/// in a 140-column terminal, where dcrd's `--maxpeers` entry and its
/// `(default: 125)` fit on one line.
#[test]
fn help_text_follows_the_terminal_width() {
    let expected = include_str!("data/help_vector_140.txt");
    assert_eq!(
        render_as_dcrd(140),
        expected,
        "help text must match go-flags at 140 columns"
    );
}

/// The help must advertise the variables the daemon actually reads.
///
/// The parity test above renders with dcrd's names on purpose, so without
/// this one nothing would notice if the production annotation drifted back
/// to `DCRD_*` — help that names a variable the code ignores is worse than
/// no annotation, because it sends an operator to set something that has
/// no effect.
#[test]
fn the_env_annotations_name_the_variables_actually_read() {
    let rendered = String::from_utf8(dcroxide_node::flags::render_help(
        "dcroxide",
        HELP_VECTOR_HOME,
        80,
    ))
    .expect("the vector home renders as UTF-8");
    for (_, var, _) in dcroxide_node::flags::ENV_DEFAULTS {
        assert!(
            rendered.contains(&format!("[${var}]")),
            "the help must annotate {var}, which the daemon reads"
        );
    }
    // And must not advertise dcrd's, which are no longer consulted.
    for stale in ["$DCRD_APPDATA", "$DCRD_ALT_DNSNAMES"] {
        assert!(
            !rendered.contains(stale),
            "the help still advertises {stale}, which the daemon ignores"
        );
    }
}
